// Handler signature: void (*func)(int)
void custom_handler(int sig) {
    // Graceful cleanup logic
    volatile int x = sig; 
}

// Registering the custom handler for Ctrl+C
// Returns the previous handler address
void (*old_h)(int) = signal(SIGINT, custom_handler);

// Built-in actions:

// 1. Reset to default behavior (e.g., termination/core dump)
signal(SIGFPE, SIG_DFL);

// 2. Ignore the signal completely
signal(SIGPIPE, SIG_IGN);

// Restoring the previous handler
signal(SIGUSR1, old_h);
